const body = $('Lead Capture Webhook').item.json.body || {};
const cfg = $json.config;
function genId() { return 'lead_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8); }
const now = new Date().toISOString();
const errors = [];
const email = (body.email || '').toString().trim().toLowerCase();
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!email) errors.push('email is required');
else if (!emailRegex.test(email)) errors.push('email format is invalid');
const firstName = (body.firstName || '').toString().trim();
const lastName = (body.lastName || '').toString().trim();
const fullName = [firstName, lastName].filter(Boolean).join(' ') || (body.fullName || '').toString().trim() || 'Unknown';
const lead = {
  leadId: (body.leadId || genId()), timestamp: now, firstName, lastName, fullName, email,
  phone: (body.phone || '').toString().trim(), company: (body.company || '').toString().trim(),
  website: (body.website || '').toString().trim(), message: (body.message || '').toString().trim(),
  service: (body.service || '').toString().trim(), source: (body.source || 'Website').toString().trim(),
  status: 'NEW', leadScore: 0, leadPriority: 'COLD', qualificationReason: '', aiSummary: '',
  firstContactedAt: '', lastContactedAt: '', nextFollowUpAt: '', followUpCount: 0,
  replyDetected: 'FALSE', ownerNotified: 'FALSE', optedOut: 'FALSE',
  lastThreadId: '', draftSubject: '', draftBody: '', approvalToken: '',
  createdAt: now, updatedAt: now
};
return [{ json: { config: cfg, lead, validation: { valid: errors.length === 0, errors } } }];

const base = $('Normalize & Validate Lead').item.json;
const cfg = base.config;
let lead = { ...base.lead };
if ($json.canonicalLeadId) lead.leadId=String($json.canonicalLeadId);
const match = $json;
const isDuplicate = !!(match && match['Lead ID'] && match['Email'] && String(match['Email']).toLowerCase() === lead.email);
let duplicateInfo = { isDuplicate: false, rowNumber: null };
if (isDuplicate) {
  duplicateInfo = { isDuplicate: true, rowNumber: match.row_number || null };
  lead.leadId = match['Lead ID'];
  lead.createdAt = match['Created At'] || lead.createdAt;
  lead.followUpCount = Number(match['Follow-up Count'] || 0);
  lead.status = match['Status'] || 'NEW';
  lead.firstContactedAt = match['First Contacted At'] || '';
  lead.lastContactedAt = match['Last Contacted At'] || '';
  lead.nextFollowUpAt = match['Next Follow-up At'] || '';
  lead.replyDetected = match['Reply Detected'] || 'FALSE';
  lead.ownerNotified = match['Owner Notified'] || 'FALSE';
  lead.optedOut = match['Opted Out'] || 'FALSE';
  lead.lastThreadId = match['Last Thread Id'] || '';
}
if (isDuplicate) return [];

return [{ json: { config: cfg, lead, validation: base.validation, duplicate: duplicateInfo } }];

const { lead, config } = $json;
const system = 'You are a B2B lead qualification assistant for a small service business. Return ONLY strict JSON, no prose, no markdown fences: '
  + '{"score": number 0-100, "priority": "HOT|WARM|COLD", "intent": "HIGH|MEDIUM|LOW", "fit": "GOOD|POSSIBLE|POOR", "reason": string, "summary": string, "recommendedAction": string}. '
  + 'Score conservatively when information is missing. Do not invent facts. Routing: 80-100 HOT, 50-79 WARM, 0-49 COLD.';
const user = 'Lead data:\n' + 'Name: ' + lead.fullName + '\n' + 'Company: ' + (lead.company || 'unknown') + '\n'
  + 'Email domain: ' + (lead.email.split('@')[1] || 'unknown') + '\n' + 'Website: ' + (lead.website || 'unknown') + '\n'
  + 'Requested service: ' + (lead.service || 'unspecified') + '\n' + 'Source: ' + (lead.source || 'unknown') + '\n'
