const prev = $('Build Qualification Prompt').item.json;

let qualification = null;
let parseError = false;
let errorDetail = '';

try {
  if ($json.error) {
    throw new Error('AI API error: ' + JSON.stringify($json.error));
  }

  // Gemini response text
  const rawText = $json?.candidates?.[0]?.content?.parts?.[0]?.text || '';

  if (!rawText) {
    throw new Error('Gemini returned no text');
  }

  const cleaned = rawText
    .replace(/```json|```/g, '')
    .trim();

  const parsed = JSON.parse(cleaned);

  const score = Math.max(
    0,
    Math.min(100, Number(parsed.score) || 0)
  );

  qualification = {
    score,
    priority: ['HOT', 'WARM', 'COLD'].includes(parsed.priority)
      ? parsed.priority
      : (score >= 80 ? 'HOT' : score >= 50 ? 'WARM' : 'COLD'),

    intent: parsed.intent || 'LOW',
    fit: parsed.fit || 'POSSIBLE',
    reason: parsed.reason || '',
    summary: parsed.summary || '',
    recommendedAction: parsed.recommendedAction || ''
  };

} catch (err) {

  parseError = true;
  errorDetail = String(err.message || err);

  qualification = {
    score: 0,
    priority: 'COLD',
    intent: 'LOW',
    fit: 'POSSIBLE',
    reason: 'AI qualification failed - manual review required',
    summary: '',
    recommendedAction: 'Manual review needed'
  };
}

return [
  {
    json: {
      ...prev,
      ai: {
        ...prev.ai,
        qualification,
        qualificationParseError: parseError,
        qualificationErrorDetail: errorDetail
      }
    }
  }
];

const data = $json || {};

const lead = data.lead || {};
const config = data.config || {};
const duplicate = data.duplicate || {};
const ai = data.ai || {};
const q = ai.qualification || {};

const now = new Date().toISOString();

const score = Math.max(
  0,
  Math.min(100, Number(q.score) || 0)
);

const priority = ['HOT', 'WARM', 'COLD'].includes(q.priority)
  ? q.priority
  : (score >= 80 ? 'HOT' : score >= 50 ? 'WARM' : 'COLD');

const updatedLead = {
  ...lead,

  leadScore: score,
  leadPriority: priority,

  qualificationReason: q.reason || '',
  aiSummary: q.summary || '',

  status:
    lead.status === 'NEW'
      ? 'QUALIFIED'
      : (lead.status || 'QUALIFIED'),

  updatedAt: now
};

return [
  {
    json: {
      ...data,
      config,
      lead: updatedLead,
      duplicate,
      ai: {
        ...ai,
        qualification: {
          ...q,
          score,
          priority
        }
      }
    }
  }
];

