const prev = $json || {};
let crypto; try { crypto = require('crypto'); } catch (e) { throw new Error('SECURE_CRYPTO_UNAVAILABLE'); }
if (!crypto || typeof crypto.randomBytes !== 'function' || typeof crypto.createHash !== 'function') throw new Error('SECURE_CRYPTO_UNAVAILABLE');
const token = crypto.randomBytes(32).toString('hex');
const approvalTokenHash = crypto.createHash('sha256').update(token,'utf8').digest('hex');
const approvalTokenExpiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
const config = $('Config (EDIT ME)').item.json.config;
return [{json:{...prev,config,approvalToken:token,approvalTokenHash,'Approval Token Hash':approvalTokenHash,'Approval Token':'','Approval Token Expires At':approvalTokenExpiresAt}}];

// Central stop-condition gate.
const now = Date.now();
const out = [];

for (const item of items) {
  const r = item.json.row;
  const cfg = item.json.config;
  const status = (r['Status'] || '').toUpperCase();
  const replyDetected = String(r['Reply Detected'] || 'FALSE').toUpperCase() === 'TRUE';
  const optedOut = String(r['Opted Out'] || 'FALSE').toUpperCase() === 'TRUE';
  const followUpCount = Number(r['Follow-up Count'] || 0);
  const maxFollowUps = Number(cfg.maxFollowUps || 3);
  const nextFollowUpAt = r['Next Follow-up At'];
  const firstContactedAt = r['First Contacted At'];

  if (replyDetected) continue;
  if (optedOut) continue;
  if (['REPLIED', 'CLOSED', 'NOT_INTERESTED', 'MEETING_BOOKED', 'CONVERTED'].includes(status)) continue;
  if (status === 'PENDING_APPROVAL') continue; // not sent yet - workflow 4's job, not this one
  if (status === 'NEW' || status === 'QUALIFIED') continue; // never contacted yet
  if (!firstContactedAt) continue; // no anchor date yet - nothing to schedule from
  if (followUpCount >= maxFollowUps) continue;
  if (!nextFollowUpAt) continue;
  if (new Date(nextFollowUpAt).getTime() > now) continue; // not due yet
  if (!r['Email']) continue; // no address, nothing to send

  out.push({ json: { config: cfg, row: r, followUpNumber: followUpCount + 1 } });
}

return out;

const { row, config, followUpNumber } = $json;
const system = 'You write a brief, friendly, non-pushy follow-up email (follow-up number ' + followUpNumber + ') for a B2B lead who has not yet replied to an earlier message. '
  + 'Keep it short (3-5 sentences), reference their original requirement, add light new value or a nudge, end with a clear easy next step. '
  + 'Do not sound automated. Return ONLY strict JSON: {"subject": string, "body": string}. No markdown fences.';
const user = 'Lead name: ' + (row['First Name'] || 'there') + '\n' + 'Company: ' + (row['Company'] || 'not provided') + '\n'
  + 'Original requirement: ' + (row['Service'] || row['Message'] || 'not specified') + '\n'
  + 'This is follow-up number: ' + followUpNumber + ' of ' + config.maxFollowUps + '\n' + 'Booking link to optionally include: ' + config.bookingUrl;
return [{ json: { ...$json, ai: { followUpSystemPrompt: system, followUpUserPrompt: user } } }];

