  }

  const cleaned = rawText
    .replace(/```json|```/g, '')
    .trim();

  const parsed = JSON.parse(cleaned);

  draft = {
    subject: parsed.subject || 'Following up',
    body: parsed.body || ''
  };

  if (!draft.body) {
    throw new Error('empty body');
  }

} catch (err) {

  parseError = true;

  const row = prev.row;

  draft = {
    subject: 'Following up, ' + (row['First Name'] || 'there'),
    body:
      'Hi ' + (row['First Name'] || 'there') + ',\n\n' +
      'Just following up on your enquiry about ' +
      (row['Service'] || 'your project') + '. ' +
      'Happy to answer any questions - feel free to book a short call: ' +
      prev.config.bookingUrl +
      '\n\nBest regards'
  };
}

return [
  {
